      && verifier.VerifyVectorOfTables(tablePos, 26 /*ARRIVALS*/, CMEArrivalVerify.Verify, false)
      && verifier.VerifyString(tablePos, 28 /*NOTE*/, false)
      && verifier.VerifyTable(tablePos, 30 /*PROVENANCE*/, PVNVerify.Verify, true)
      && verifier.VerifyString(tablePos, 32 /*SOURCE_CID*/, false)
      && verifier.VerifyString(tablePos, 34 /*SOURCE_DIGEST*/, false)
      && verifier.VerifyString(tablePos, 36 /*RETRIEVED_AT*/, false)
      && verifier.VerifyTableEnd(tablePos);
  }
}
